public static int calculateDifficulty(SudokuBoard board) {
    int filledCells = 0;
    for (int row = 0; row < SudokuBoard.SIZE; row++) {
        for (int col = 0; col < SudokuBoard.SIZE; col++) {
            if (board.get(row, col) != 0) {
                filledCells++;
            }
        }
