```csharp
public static boolean isSolved(SudokuBoard board) {
    // Check that every row, column, and sub-grid contains the numbers 1-9 exactly once
    for (int i = 0; i < SudokuBoard.SIZE; i++) {
        if (!isValidGroup(getRow(board, i)) || !isValidGroup(getColumn(board, i)) || !isValidGroup(getSubgrid(board, i))) {
            return false;
        }
    }

    // If all groups are valid, the board is solved
    return true;
}

private static boolean isValidGroup(List<Integer> group) {
    // Check that the group contains the numbers 1-9 exactly once
    boolean[] seen = new boolean[SudokuBoard.SIZE];
    for (int i = 0; i < SudokuBoard.SIZE; i++) {
        int value = group.get(i);
        if (value == 0) {
            return false;  // group is not complete
        } else if (seen[value - 1]) {
            return false;  // value is already seen in the group
        } else {
            seen[value - 1] = true;
        }
    }
    return true;
}

private static List<Integer> getRow(SudokuBoard board, int row) {
    List<Integer> rowValues = new ArrayList<>();
    for (int col = 0; col < SudokuBoard.SIZE; col++) {
        rowValues.add(board.get(row, col));
    }
    return rowValues;
}

private static List<Integer> getColumn(SudokuBoard board, int col) {
    List<Integer> colValues = new ArrayList<>();
    for (int row = 0; row < SudokuBoard.SIZE; row++) {
        colValues.add(board.get(row, col));
    }
    return colValues;
}

private static List<Integer> getSubgrid(SudokuBoard board, int subgrid) {
    List<Integer> subgridValues = new ArrayList<>();
    int rowStart = (subgrid / SudokuBoard.SUBGRID_SIZE) * SudokuBoard.SUBGRID_SIZE;
    int colStart = (subgrid % SudokuBoard.SUBGRID_SIZE) * SudokuBoard.SUBGRID_SIZE;
    for (int row = rowStart; row < rowStart + SudokuBoard.SUBGRID_SIZE; row++) {
        for (int col = colStart; col < colStart + SudokuBoard.SUBGRID_SIZE; col++) {
            subgridValues.add(board.get(row, col));
        }
    }
    return subgridValues;
}
