1. Module Pattern: The module pattern is a design pattern in JavaScript that provides encapsulation and abstraction by keeping specific parts of a codebase isolated from each other. In JavaScript, you can create modules using an IIFE (Immediately Invoked Function Expression) and the `module.exports` object.

For example:
```javascript
let bankAccount = (function() {
  let balance = 0;

  function deposit(amount) {
    balance += amount;
  }

  function withdraw(amount) {
    if (amount <= balance) {
      balance -= amount;
      return true;
    } else {
      return false;
    }
  }

  return {
    deposit: deposit,
    withdraw: withdraw,
    getBalance: function() {
      return balance;
    }
  };
})();

bankAccount.deposit(500);
bankAccount.withdraw(200);
console.log(bankAccount.getBalance()); // output: 300
```
In this example, the bank account functionality is encapsulated within an IIFE and the `module.exports` object is used to expose only the necessary functions to the user. This allows the user to interact with the bank account module without knowing its implementation details.

Encapsulation is the practice of bundling data and behavior that manipulate that data within a single unit, such as an object. Here are some different ways to achieve encapsulation in JavaScript:

1. Using Constructor Functions: Constructor functions are functions that create and initialize objects. By defining variables within a constructor function using the `var`, `let`, or `const` keywords, those variables become private to that function, and cannot be accessed or modified from outside the function.

For example:
```javascript
function BankAccount(balance) {
  var _balance = balance;

  this.deposit = function(amount) {
    _balance += amount;
  };

  this.withdraw = function(amount) {
    if (amount <= _balance) {
      _balance -= amount;
      return true;
    } else {
      return false;
    }
  };

  this.getBalance = function() {
    return _balance;
  };
}

var myAccount = new BankAccount(1000);
myAccount.deposit(500);
myAccount.withdraw(200);
console.log(myAccount.getBalance()); // output: 1300
```
In this example, the `BankAccount` constructor function encapsulates the balance data and the `deposit()`, `withdraw()`, and `getBalance()` functions that operate on that data.

1. Using Classes: Classes in JavaScript are a newer syntax for defining objects with constructors and methods. Like constructor functions, variables defined within a class using the `let` or `const` keywords are private to that class and cannot be accessed or modified from outside the class.

For example:
```javascript
class BankAccount {
  constructor(balance) {
    let _balance = balance;

    this.deposit = function(amount) {
      _balance += amount;
    };

    this.withdraw = function(amount) {
      if (amount <= _balance) {
        _balance -= amount;
        return true;
      } else {
        return false;
      }
    };

    this.getBalance = function() {
      return _balance;
    };
  }
}

let myAccount = new BankAccount(1000);
myAccount.deposit(500);
myAccount.withdraw(200);
console.log(myAccount.getBalance()); // output: 1300
```
In this example, the `BankAccount` class encapsulates the balance data and the `deposit()`, `withdraw()`, and `getBalance()` methods that operate on that data.

1. Using Closures: Closures are functions that have access to variables in their outer (enclosing) function scope. By defining a function that returns an object with methods that access variables in the enclosing function, those variables become private to that function and cannot be accessed or modified from outside the function.

For example:
```javascript
function bankAccount(balance) {
  let _balance = balance;

  function deposit(amount) {
    _balance += amount;
  }

  function withdraw(amount) {
    if (amount <= _balance) {
      _balance -= amount;
      return true;
    } else {
      return false;
    }
  }

  function getBalance() {
    return _balance;
  }

  return {
    deposit: deposit,
    withdraw: withdraw,
    getBalance: getBalance
  };
}

let myAccount = bankAccount(1000);
myAccount.deposit(500);
myAccount.withdraw(200);
console.log(myAccount.getBalance()); // output: 1300
```
In this example, the `bankAccount` function encapsulates the balance data and the `deposit()`, `withdraw()`, and `getBalance()` functions that operate on that data. The function returns an object with methods that have access to the variables within the function scope.

